import itertools

def get_sorted_count(config):
    adjacencies = 0
    for i in range(len(config) - 1):
        if config[i] != config[i+1]:
            adjacencies += 1
    return adjacencies

def step(config, k):
    idx = k - 1
    coin = config[idx]
    left = idx
    while left > 0 and config[left-1] == coin:
        left -= 1
    right = idx
    while right < len(config) - 1 and config[right+1] == coin:
        right += 1
    block = config[left:right+1]
    remaining = config[:left] + config[right+1:]
    return list(block) + list(remaining)

def check_k(n, k):
    total = 2 * n
    initial_configs = []
    for config in itertools.product(['A', 'C'], repeat=total):
        if config.count('A') == n and config.count('C') == n:
            initial_configs.append(tuple(config))

    for config in initial_configs:
        current = list(config)
        visited = set()
        while True:
            state = tuple(current)
            if state in visited:
                return False
            visited.add(state)
            if get_sorted_count(current) <= 1:
                break
            current = step(current, k)
    return True

for k in range(1, 5):
    print(f"k={k}: {check_k(2, k)}")

